package ingest

import("encoding/json";"io";"strconv";"github.com/softrenzu/Prometheus/internal/engine")
func ParseOTLPJSON(r io.Reader,tenant string)([]engine.Sample,error){var req otlpRequest;if err:=json.NewDecoder(io.LimitReader(r,64<<20)).Decode(&req);err!=nil{return nil,err};out:=[]engine.Sample{};for _,rm:=range req.ResourceMetrics{resource:=attrs(rm.Resource.Attributes);for _,sm:=range rm.ScopeMetrics{for _,m:=range sm.Metrics{if m.Gauge!=nil{out=append(out,convertPoints(tenant,m.Name,resource,m.Gauge.DataPoints)...)}else if m.Sum!=nil{out=append(out,convertPoints(tenant,m.Name,resource,m.Sum.DataPoints)...)}else if m.Histogram!=nil{for _,p:=range m.Histogram.DataPoints{labels:=merge(resource,attrs(p.Attributes));ts:=nanoToMilli(p.TimeUnixNano);if p.Count!=""{if v,err:=strconv.ParseFloat(p.Count,64);err==nil{out=append(out,engine.Sample{Tenant:tenant,Metric:m.Name+"_count",Labels:labels,Timestamp:ts,Value:v})}};if p.Sum!=nil{out=append(out,engine.Sample{Tenant:tenant,Metric:m.Name+"_sum",Labels:engine.CloneLabels(labels),Timestamp:ts,Value:*p.Sum})}}}}}};return out,nil}
func convertPoints(tenant,name string,resource map[string]string,points []otlpPoint)[]engine.Sample{out:=[]engine.Sample{};for _,p:=range points{var v float64;ok:=false;if p.AsDouble!=nil{v=*p.AsDouble;ok=true};if p.AsInt!=nil{if f,err:=strconv.ParseFloat(*p.AsInt,64);err==nil{v=f;ok=true}};if ok{out=append(out,engine.Sample{Tenant:tenant,Metric:name,Labels:merge(resource,attrs(p.Attributes)),Timestamp:nanoToMilli(p.TimeUnixNano),Value:v})}};return out}
